package com.hozefa.threepattipro.nativeapp;
import android.graphics.Rect;import android.view.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;import java.util.*;import static org.junit.Assert.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;import static androidx.test.espresso.assertion.ViewAssertions.*;import static org.hamcrest.Matchers.*;

public class ScoreChartUiTest {
    private void set(MainActivity a,String name,Object value){try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(a,value);}catch(Exception e){throw new AssertionError(e);}}
    private Object get(MainActivity a,String name){try{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(a);}catch(Exception e){throw new AssertionError(e);}}
    private void render(MainActivity a){try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod("render",boolean.class);m.setAccessible(true);m.invoke(a,false);}catch(Exception e){throw new AssertionError(e);}}
    private Map<String,Object> m(Object...p){return FirebaseGateway.map(p);}
    private List<Map<String,Object>> list(Map<String,Object>...p){return new ArrayList<>(Arrays.asList(p));}
    private ScoreTrendChart chart(MainActivity a){return ((View)get(a,"content")).findViewWithTag("all-player-score-chart");}
    private Map<String,Object> round(String id,int n,String session,Object...scores){return m("id",id,"type","hukum","timestamp","2026-10-29T10:00:0"+n+"Z","sessionId",session,"hukumName","Player 0","playerIds",Arrays.asList("p0","p1","p2","p3","p4","p5"),"scoreChanges",m(scores));}
    private void seed(MainActivity a){((FirebaseGateway)get(a,"api")).stop();set(a,"tab",3);set(a,"ranksSessions",false);set(a,"loggedIn",false);List<Map<String,Object>> players=new ArrayList<>();for(int i=0;i<6;i++)players.add(m("id","p"+i,"name","Player "+i));a.dataUpdated(players,list(round("r1",1,"first","p0",310,"p1",155,"p2",0,"p3",-155,"p4",50,"p5",100),round("r2",2,"first","p0",-155,"p1",0,"p2",310,"p3",155,"p4",-50,"p5",100),round("r3",3,"second","p0",700,"p1",-78,"p2",155,"p3",0,"p4",155,"p5",-155)),list(m("id","first","sessionName","Evening session","startTime","2026-10-29T09:00:00Z","endTime","2026-10-29T10:00:03Z"),m("id","second","sessionName","Other session","startTime","2026-10-29T10:00:03Z","endTime","2026-10-29T11:00:00Z")));a.historyDeferred(false);a.syncState(true);render(a);}
    private void capture(String name)throws Exception{try(java.io.InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand("screencap -p /data/local/tmp/"+name+".png"))){byte[] buffer=new byte[1024];while(in.read(buffer)!=-1){}}}
    @Before public void isolated(){assertTrue(BuildConfig.USE_EMULATORS);InstrumentationRegistry.getInstrumentation().getTargetContext().getSharedPreferences("preferences",0).edit().remove("ranks_sessions").remove("ranks_session_id").putString("motion","off").commit();}
    @Test public void adjacentButtonOpensAllPlayersAndRoundControlsRetainLegendSelection()throws Exception{
        try(ActivityScenario<MainActivity>s=ActivityScenario.launch(MainActivity.class)){NativeTestUi.awaitMotionIdle(s);s.onActivity(this::seed);onView(withText("Score Chart")).perform(scrollTo()).check(matches(isDisplayed()));onView(withText("Big Scoreboard")).check(matches(isDisplayed()));
            final Rect[] bounds={new Rect(),new Rect()};onView(withText("Big Scoreboard")).check((v,e)->v.getGlobalVisibleRect(bounds[0]));onView(withText("Score Chart")).check((v,e)->v.getGlobalVisibleRect(bounds[1]));assertEquals(bounds[0].top,bounds[1].top);assertTrue(bounds[1].left>bounds[0].left);
            onView(withText("Score Chart")).perform(click());NativeTestUi.awaitMotionIdle(s);s.onActivity(a->{assertEquals(11,get(a,"tab"));assertEquals(6,chart(a).model.series.size());Set<Integer> colors=new HashSet<>();for(int n=0;n<6;n++)colors.add(chart(a).color(n));assertEquals(6,colors.size());assertEquals(855,chart(a).model.frames.get(3).values[0]);});capture("score-chart-lifetime");
            onView(withContentDescription("Previous chart round")).perform(scrollTo(),click());s.onActivity(a->assertEquals(2,chart(a).model.frames.get(chart(a).cursor()).round));onView(withContentDescription("Latest chart round")).perform(click());
            onView(withContentDescription("Show line: Player 0")).perform(scrollTo(),click());s.onActivity(a->assertTrue(chart(a).state.hidden.contains("p0")));
            onView(withContentDescription("Close Score Chart")).perform(scrollTo(),click());onView(withText("Score Chart")).perform(scrollTo(),click());s.onActivity(a->{assertTrue(chart(a).state.hidden.contains("p0"));assertEquals(3,chart(a).model.frames.get(chart(a).cursor()).round);});
        }
    }
    @Test public void sessionChartIsIsolatedAndVerticalTouchScrollWorks()throws Exception{
        try(ActivityScenario<MainActivity>s=ActivityScenario.launch(MainActivity.class)){NativeTestUi.awaitMotionIdle(s);s.onActivity(this::seed);onView(withText("Score Chart")).perform(scrollTo(),click());onView(withText("Sessions")).perform(scrollTo(),click());onView(withContentDescription("Select Session")).perform(scrollTo(),click());onView(withText("Evening session")).perform(scrollTo(),click());NativeTestUi.awaitMotionIdle(s);
            s.onActivity(a->{assertEquals("first",get(a,"selectedSessionId"));assertEquals(2,chart(a).model.totalRounds);assertEquals(155,chart(a).model.frames.get(2).values[0]);});onView(withTagValue(is("all-player-score-chart"))).perform(scrollTo());int[] before={0};s.onActivity(a->before[0]=((android.widget.ScrollView)get(a,"scroll")).getScrollY());onView(withTagValue(is("all-player-score-chart"))).perform(swipeUp());s.onActivity(a->assertTrue(((android.widget.ScrollView)get(a,"scroll")).getScrollY()>before[0]));capture("score-chart-session");
            onView(withContentDescription("Close Score Chart")).perform(scrollTo(),click());onView(withText("Big Scoreboard")).perform(scrollTo(),click());s.onActivity(a->{assertEquals("first",get(a,"selectedSessionId"));assertTrue((boolean)get(a,"ranksSessions"));});
        }
    }
}
